#include <algorithm>
#include <array>
#include <cctype>
#include <iostream>
#include <memory>
#include <optional>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

class Dictionary
{
public:
    bool insert(const std::string& word)
    {
        if (contains(word)) return false;
        Node* n = &root_;
        ++n->passing;
        for (char ch : word)
        {
            auto& child = n->next[ch - 'a'];
            if (!child) child = std::make_unique<Node>();
            n = child.get();
            ++n->passing;
        }
        n->word = true;
        return true;
    }

    bool erase(const std::string& word)
    {
        if (!contains(word)) return false;
        Node* n = &root_;
        --n->passing;
        for (char ch : word)
        {
            auto& child = n->next[ch - 'a'];
            if (--child->passing == 0) { child.reset(); return true; }
            n = child.get();
        }
        n->word = false;
        return true;
    }

    bool contains(const std::string& word) const
    {
        const Node* n = walk(word);
        return n && n->word;
    }

    int countPrefix(const std::string& prefix) const
    {
        const Node* n = walk(prefix);
        return n ? n->passing : 0;
    }

    int size() const { return root_.passing; }

    std::vector<std::string> complete(const std::string& prefix, std::size_t limit) const
    {
        std::vector<std::string> out;
        std::string current = prefix;
        if (const Node* n = walk(prefix)) collect(n, current, limit, out);
        return out;
    }

    // Every word within maxDistance of target, sorted by (distance, word).
    std::vector<std::pair<int, std::string>> near(const std::string& target, int maxDistance) const
    {
        std::vector<std::pair<int, std::string>> found;
        std::vector<int> row(target.size() + 1);
        for (std::size_t j = 0; j <= target.size(); ++j) row[j] = static_cast<int>(j);
        std::string current;
        if (root_.word && row.back() <= maxDistance) found.push_back({ row.back(), "" });
        for (int c = 0; c < 26; ++c)
            if (root_.next[c]) search(root_.next[c].get(), static_cast<char>('a' + c), target, row, maxDistance, current, found);
        // The walk visits words alphabetically; a stable pass by distance keeps that order within each distance.
        std::vector<std::pair<int, std::string>> sorted;
        for (int d = 0; d <= maxDistance; ++d)
            for (const auto& f : found)
                if (f.first == d) sorted.push_back(f);
        return sorted;
    }

private:
    struct Node
    {
        std::array<std::unique_ptr<Node>, 26> next{};
        bool word = false;
        int passing = 0;
    };

    const Node* walk(const std::string& s) const
    {
        const Node* n = &root_;
        for (char ch : s)
        {
            n = n->next[ch - 'a'].get();
            if (!n) return nullptr;
        }
        return n;
    }

    static void collect(const Node* n, std::string& current, std::size_t limit, std::vector<std::string>& out)
    {
        if (out.size() >= limit) return;
        if (n->word) out.push_back(current);
        for (int c = 0; c < 26 && out.size() < limit; ++c)
            if (n->next[c])
            {
                current.push_back(static_cast<char>('a' + c));
                collect(n->next[c].get(), current, limit, out);
                current.pop_back();
            }
    }

    static void search(const Node* n, char letter, const std::string& target, const std::vector<int>& above, int maxDistance,
                       std::string& current, std::vector<std::pair<int, std::string>>& found)
    {
        current.push_back(letter);
        std::vector<int> row(above.size());
        row[0] = above[0] + 1;
        for (std::size_t j = 1; j < row.size(); ++j)
            row[j] = std::min({ above[j] + 1, row[j - 1] + 1, above[j - 1] + (target[j - 1] == letter ? 0 : 1) });
        if (n->word && row.back() <= maxDistance) found.push_back({ row.back(), current });
        if (*std::min_element(row.begin(), row.end()) <= maxDistance)              // otherwise no word below can be close enough
            for (int c = 0; c < 26; ++c)
                if (n->next[c]) search(n->next[c].get(), static_cast<char>('a' + c), target, row, maxDistance, current, found);
        current.pop_back();
    }

    Node root_;
};

static std::optional<std::string> lowerWord(const std::string& s)
{
    std::string out;
    for (char ch : s)
    {
        if (!std::isalpha(static_cast<unsigned char>(ch))) return std::nullopt;
        out += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
    }
    return out;
}

static std::vector<std::string> wordsIn(const std::string& text)
{
    std::vector<std::string> out;
    std::string current;
    for (char ch : text)
    {
        if (std::isalpha(static_cast<unsigned char>(ch))) current += static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        else if (!current.empty()) { out.push_back(current); current.clear(); }
    }
    if (!current.empty()) out.push_back(current);
    return out;
}

static std::string count(long long n, const char* one, const char* many) { return std::to_string(n) + " " + (n == 1 ? one : many); }

int main()
{
    Dictionary dict;
    std::string line;
    while (std::getline(std::cin, line))
    {
        std::istringstream in(line);
        std::vector<std::string> w;
        for (std::string word; in >> word;) w.push_back(word);
        if (w.empty()) continue;
        const std::string& cmd = w[0];

        auto usage = [&](const char* text) { std::cout << "error: usage: " << text << '\n'; };
        auto badWord = [&](const std::string& word) { std::cout << "error: words may only contain letters: '" << word << "'\n"; };

        if (cmd == "add")
        {
            if (w.size() < 2) { usage("add <word> ..."); continue; }
            std::vector<std::string> words;
            bool ok = true;
            for (std::size_t i = 1; i < w.size() && ok; ++i)
            {
                auto lw = lowerWord(w[i]);
                if (!lw) { badWord(w[i]); ok = false; }
                else words.push_back(*lw);
            }
            if (!ok) continue;
            long long added = 0;
            for (const auto& word : words) added += dict.insert(word);
            std::cout << "added " << count(added, "word", "words") << '\n';
        }
        else if (cmd == "remove")
        {
            if (w.size() != 2) { usage("remove <word>"); continue; }
            auto lw = lowerWord(w[1]);
            if (!lw) { badWord(w[1]); continue; }
            if (dict.erase(*lw)) std::cout << "removed " << *lw << '\n';
            else std::cout << "error: '" << *lw << "' is not in the dictionary\n";
        }
        else if (cmd == "check")
        {
            if (w.size() < 2) { usage("check <text>"); continue; }
            std::vector<std::string> words = wordsIn(line.substr(line.find("check") + 5));
            if (words.empty()) { std::cout << "nothing to check\n"; continue; }
            std::vector<std::string> reported;
            for (const auto& word : words)
            {
                if (dict.contains(word) || std::find(reported.begin(), reported.end(), word) != reported.end()) continue;
                reported.push_back(word);
                auto near = dict.near(word, 2);
                std::vector<std::string> suggestions;
                for (const auto& [d, s] : near)
                    if (d >= 1 && suggestions.size() < 3) suggestions.push_back(s);
                if (suggestions.empty()) { std::cout << word << ": no suggestions\n"; continue; }
                std::cout << word << ": did you mean ";
                for (std::size_t i = 0; i < suggestions.size(); ++i) std::cout << (i ? ", " : "") << suggestions[i];
                std::cout << "?\n";
            }
            if (reported.empty()) std::cout << "all words are spelled correctly\n";
        }
        else if (cmd == "complete")
        {
            if (w.size() != 2) { usage("complete <prefix>"); continue; }
            auto p = lowerWord(w[1]);
            if (!p) { badWord(w[1]); continue; }
            auto words = dict.complete(*p, 5);
            std::cout << *p << ':';
            if (words.empty()) std::cout << " no words";
            for (std::size_t i = 0; i < words.size(); ++i) std::cout << (i ? ", " : " ") << words[i];
            std::cout << '\n';
        }
        else if (cmd == "suggest")
        {
            if (w.size() != 3) { usage("suggest <word> <max>"); continue; }
            auto target = lowerWord(w[1]);
            if (!target) { badWord(w[1]); continue; }
            if (w[2].size() != 1 || w[2][0] < '0' || w[2][0] > '3') { std::cout << "error: max must be a whole number from 0 to 3\n"; continue; }
            auto near = dict.near(*target, w[2][0] - '0');
            if (near.empty()) { std::cout << *target << ": no suggestions\n"; continue; }
            std::cout << *target << ':';
            for (std::size_t i = 0; i < near.size() && i < 10; ++i) std::cout << (i ? ", " : " ") << near[i].second << " (" << near[i].first << ')';
            std::cout << '\n';
        }
        else if (cmd == "prefix")
        {
            if (w.size() != 2) { usage("prefix <p>"); continue; }
            auto p = lowerWord(w[1]);
            if (!p) { badWord(w[1]); continue; }
            int n = dict.countPrefix(*p);
            std::cout << n << (n == 1 ? " word starts with " : " words start with ") << *p << '\n';
        }
        else if (cmd == "count")
        {
            if (w.size() != 1) { usage("count"); continue; }
            std::cout << count(dict.size(), "word", "words") << '\n';
        }
        else std::cout << "error: unknown command '" << cmd << "'\n";
    }
}
